package com.xauusd.pro2030.data

import android.content.ContentValues
import android.content.Context
import android.database.sqlite.SQLiteDatabase
import android.database.sqlite.SQLiteOpenHelper

/** Small local SQLite store for signal history; no signal is generated by this class. */
class SignalRepository(context: Context) {
    private val helper = SignalHistoryDatabase(context.applicationContext)

    fun saveHistory(signal: SignalHistory): Long {
        val values = ContentValues().apply {
            put("symbol", signal.symbol)
            put("signal_type", signal.signalType)
            put("score", signal.score)
            put("timestamp", signal.timestamp)
        }
        return helper.writableDatabase.insertOrThrow(SignalHistoryDatabase.TABLE, null, values)
    }

    fun loadHistory(limit: Int = 100): List<SignalHistory> {
        require(limit > 0) { "limit must be positive" }
        val result = mutableListOf<SignalHistory>()
        helper.readableDatabase.query(
            SignalHistoryDatabase.TABLE,
            arrayOf("id", "symbol", "signal_type", "score", "timestamp"),
            null, null, null, null, "timestamp DESC", limit.toString()
        ).use { cursor ->
            while (cursor.moveToNext()) {
                result += SignalHistory(
                    id = cursor.getLong(0),
                    symbol = cursor.getString(1),
                    signalType = cursor.getString(2),
                    score = cursor.getDouble(3),
                    timestamp = cursor.getLong(4)
                )
            }
        }
        return result
    }

    fun clearHistory() = helper.writableDatabase.delete(SignalHistoryDatabase.TABLE, null, null)
    fun close() = helper.close()
}

private class SignalHistoryDatabase(context: Context) : SQLiteOpenHelper(context, "signal-history.db", null, 1) {
    override fun onCreate(db: SQLiteDatabase) {
        db.execSQL("CREATE TABLE $TABLE (id INTEGER PRIMARY KEY AUTOINCREMENT, symbol TEXT NOT NULL, signal_type TEXT NOT NULL, score REAL NOT NULL, timestamp INTEGER NOT NULL)")
    }
    override fun onUpgrade(db: SQLiteDatabase, oldVersion: Int, newVersion: Int) {
        // Add explicit migrations here before increasing the schema version.
    }
    companion object { const val TABLE = "signal_history" }
}
